<?php
defined('ABSPATH') || exit;

/** Bounded, admin-owned presentation and instruction entries. No remote actions. */
final class AISA_Experience {
    public static function sizes() {
        return array('launcher_size'=>array(40,80,48,'Launcher size'),'launcher_icon_size'=>array(16,36,20,'Launcher icon'),'panel_width'=>array(300,520,360,'Chat width'),'panel_height'=>array(360,720,500,'Chat height'),'chat_font_size'=>array(12,20,13,'Message text'),'action_font_size'=>array(11,16,11,'Action text'),'composer_height'=>array(40,80,40,'Message input height'),'bubble_radius'=>array(4,24,12,'Message corners'));
    }
    public static function defaults() { $v=array('launcher_mobile'=>'icon','instruction_entries'=>array());foreach(self::sizes()as$key=>$rule)$v[$key]=$rule[2];return $v; }
    public static function widget_keys() { return array_merge(array_keys(self::sizes()),array('launcher_mobile')); }
    public static function save_widget($p,$s) {
        foreach(self::sizes()as$key=>$rule)if(array_key_exists($key,$p)){
            if(!is_string($p[$key])||!preg_match('/^[0-9]{1,3}$/D',$p[$key])||(int)$p[$key]<$rule[0]||(int)$p[$key]>$rule[1])return new WP_Error('widget_size','Choose a size within the displayed range.');$s[$key]=(int)$p[$key];
        }
        if(array_key_exists('launcher_mobile',$p)){if(!is_string($p['launcher_mobile'])||!in_array($p['launcher_mobile'],array('icon','label'),true))return new WP_Error('widget_mobile','Choose a listed mobile launcher style.');$s['launcher_mobile']=$p['launcher_mobile'];}
        return $s;
    }
    public static function instructions($raw) {
        if(!is_array($raw)||count($raw)>10)return new WP_Error('instructions','Use up to ten instruction entries.');$out=array();$bytes=0;
        foreach($raw as$row){if(!is_array($row))return new WP_Error('instructions','Invalid instruction entry.');$title=$row['title']??'';$text=$row['text']??'';
            if(!is_string($title)||!is_string($text)||strlen($title)>80||strlen($text)>1200||!preg_match('//u',$title.$text)||strpos($title.$text,"\0")!==false)return new WP_Error('instructions','Use plain titles up to80 bytes and instructions up to1200 bytes.');
            $title=sanitize_text_field($title);$text=sanitize_textarea_field($text);if(trim($title)===''&&trim($text)==='')continue;if(trim($title)===''||trim($text)==='')return new WP_Error('instructions','Each instruction needs a title and text.');$bytes+=strlen($title.$text);if($bytes>8000)return new WP_Error('instructions','Instruction entries exceed8000 bytes.');$out[]=array('title'=>$title,'text'=>$text,'enabled'=>empty($row['enabled'])?0:1);
        }return $out;
    }
    public static function prompt($s) { $rows=self::instructions($s['instruction_entries']??array());if(is_wp_error($rows))return ''; $out='';foreach($rows as$row)if($row['enabled'])$out.="\n".$row['title'].': '.$row['text'];return $out; }
    public static function render_instructions($s) {
        echo '<div class="aisa-card" data-aisa-instructions><h3>Instruction collection</h3><p>Create separate guidance for tone, answers and support workflow. Entries are administrator guidance, not authority to bypass privacy, purchase checks or factual sources.</p><input form="aisa-settings" type="hidden" name="instruction_entries_present" value="1"><div data-aisa-instruction-list>';
        $rows=self::instructions($s['instruction_entries']??array());if(is_wp_error($rows))$rows=array();for($i=0;$i<10;$i++){$row=$rows[$i]??array('title'=>'','text'=>'','enabled'=>1);echo '<fieldset data-aisa-instruction-row'.($i>=max(1,count($rows))?' hidden':'').'><legend>Instruction '.($i+1).'</legend><label class="aisa-field"><span>Title</span><input form="aisa-settings" name="instruction_entries['.$i.'][title]" maxlength="80" value="'.esc_attr($row['title']).'"></label><label class="aisa-field"><span>Instruction (up to1200 bytes)</span><textarea form="aisa-settings" name="instruction_entries['.$i.'][text]" rows="3">'.esc_textarea($row['text']).'</textarea></label><label><input form="aisa-settings" type="checkbox" name="instruction_entries['.$i.'][enabled]" value="1" '.checked($row['enabled'],1,false).'> Active</label> <button type="button" class="button" data-aisa-remove-instruction>Remove entry</button></fieldset>';}
        echo '</div><button type="button" class="button" data-aisa-add-instruction>Add instruction</button><p class="aisa-help" role="status" data-aisa-instruction-status>Up to10 entries /8000 bytes total. Changes apply only after Save this view.</p></div>';
    }
    public static function render_widget($s) {
        echo '<div class="aisa-card"><h3>Size & mobile launcher</h3><p>Choose readable sizes; mobile panels still fit the visible screen.</p><div class="aisa-field-grid">';foreach(self::sizes()as$key=>$rule){echo '<label class="aisa-field"><span>'.esc_html($rule[3]).' ('.$rule[0].'–'.$rule[1].'px)</span><input form="aisa-settings" type="number" name="'.esc_attr($key).'" min="'.$rule[0].'" max="'.$rule[1].'" value="'.(int)$s[$key].'"></label>';}
        echo '</div><label class="aisa-field"><span>Mobile launcher</span><select form="aisa-settings" name="launcher_mobile"><option value="icon" '.selected($s['launcher_mobile'],'icon',false).'>Icon only (default)</option><option value="label" '.selected($s['launcher_mobile'],'label',false).'>Icon and label</option></select></label></div>';
        $presets=array('digital'=>array('Digital products',array('File formats','Which file formats are available?'),array('Download help','How do I find my account Downloads?'),array('Usage rights','What usage rights are confirmed by your public policy?')),'shop'=>array('E-commerce',array('Product details','Help me understand your public product information.'),array('Shipping','What shipping information is confirmed?'),array('Returns','What return policy is confirmed?')),'software'=>array('Software',array('Compatibility','Which platforms are explicitly supported?'),array('License','What license terms are confirmed?'),array('Updates','What update policy is confirmed?')),'courses'=>array('Courses',array('Course content','What course topics are publicly listed?'),array('Access','What course access terms are confirmed?'),array('Requirements','What prerequisites are publicly listed?')),'services'=>array('Services',array('Services','Which services are publicly described?'),array('Process','What service process is publicly described?'),array('Contact','How can I contact your team?')));
        echo '<div class="aisa-card" data-aisa-niches="'.esc_attr(wp_json_encode($presets)).'"><h3>Quick-action collections</h3><p>Select a business category to preview three optional questions. Use collection deliberately fills the custom rows below; Save this view applies them. Existing preset enable/disable choices stay unchanged.</p><label class="aisa-field"><span>Business category</span><select data-aisa-niche>';foreach($presets as$id=>$row)echo '<option value="'.esc_attr($id).'">'.esc_html($row[0]).'</option>';echo '</select></label><ul data-aisa-niche-summary></ul><button type="button" class="button" data-aisa-use-niche>Use collection in custom actions</button><p role="status" data-aisa-niche-status></p></div>';
    }
    public static function render_notifications($field) {
        echo '<div class="aisa-card"><h3>Notification destinations</h3><p>Choose a channel. Saving configuration never sends a test message.</p><div data-aisa-channel-tabs><div class="aisa-subnav" role="tablist" aria-label="Notification channels">';foreach(array('email'=>'Email','telegram'=>'Telegram','relay'=>'HTTPS relay')as$id=>$name)echo '<button type="button" role="tab" data-aisa-channel="'.$id.'" aria-selected="'.($id==='email'?'true':'false').'">'.$name.'</button>';echo '</div>';
        echo '<section data-aisa-channel-panel="email"><h4>Email alerts</h4>';$field('notify_email','Admin notification email','email');echo '<ol><li>Enter an existing mailbox your team monitors. No API token is required here.</li><li>Configure WordPress mail/SMTP separately with your mail provider.</li><li>Verify delivery with an approved test destination before relying on alerts. Staging email suppression remains in effect.</li></ol></section>';
        echo '<section data-aisa-channel-panel="telegram"><h4>Telegram alerts</h4>';$field('telegram_secret','Telegram bot token','password');$field('telegram_chat','Telegram chat ID');echo '<ol><li>Open the official <a href="https://t.me/BotFather" target="_blank" rel="noopener noreferrer">BotFather</a>, use /newbot and complete its prompts. Paste its bot token only into this private token field.</li><li>For your own chat, start the bot. For a group, add it and send a message. For a channel, add the bot with permission to post.</li><li>Use your own secure local Telegram Bot API getUpdates setup to read message.chat.id or channel_post.chat.id. Group/channel IDs can be negative; an existing webhook can prevent getUpdates. Do not paste a token into a browser URL, screenshots or support chat.</li><li>Enter the exact ID (or your public channel @username), save, then test only with an approved destination.</li></ol><p><a href="https://core.telegram.org/bots/tutorial" target="_blank" rel="noopener noreferrer">Official bot setup</a> · <a href="https://core.telegram.org/bots/api#getupdates" target="_blank" rel="noopener noreferrer">Chat ID / updates reference</a></p><p>Outbound administrator alerts only; not two-way customer chat. A blank token retains the saved encrypted value.</p></section>';
        echo '<section data-aisa-channel-panel="relay"><h4>HTTPS relay alerts</h4>';$field('webhook_secret','HTTPS relay URL','password');echo '<ol><li>Create or select your approved automation receiver separately.</li><li>Copy its public HTTPS incoming-webhook URL into this private field. This plugin does not create a receiver, token or WhatsApp connection.</li><li>Keep URL credentials private and verify the receiver with synthetic data only after approval.</li></ol><p>Only the existing bounded event payload is forwarded. It does not grant access to chats, issue refunds or confirm payment. Blank URL keeps its saved encrypted value.</p></section></div></div>';
    }
    public static function render_storage() {
        echo '<div class="aisa-card"><h3>Chat storage protection</h3><p>Saved conversations have fixed count and text-size limits. Old chats are cleaned automatically when WordPress scheduled jobs and database operations are available. No unlimited chat archive is created.</p><p>Deleting this plugin removes saved customer conversations, unreviewed chat excerpts and indexed administrator chat sessions. Configuration, deliberately approved knowledge and structured handoff tickets remain unless full data removal was explicitly selected separately. Temporary public-reference caches expire; provider copies and independent hosting backups are outside this plugin cleanup.</p></div>';
    }
}
